import MainHeading from '@/components/heading/MainHeading';
import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { format } from 'date-fns';
import Submission from './Submission';
import ContractInfo from './ContractInfo';
import PeriodDetails from './PeriodDetails';
import AllowanceDetails from './AllowanceDetails';
import SalaryDetails from './SalaryDetails';
import FileInput from './FileInput';
import { AddContractFormValues, AddContractSchema } from '../schemas/addContract/add-contract-schema';
import InsuranceDetails from './InsuranceDetails';

interface Props {
    employee?: Employee | null;
}

export default function AddContractForm({ employee }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const defaultValues = useMemo(
        () => ({
            employee_id: '',
            salary_cycle: '',
            skip_allowance: false,
            skip_deduction: false,
            allowance_type: '',
            deduction_type: '',
        }),
        [employee],
    );

    const form = useForm<AddContractFormValues>({
        resolver: zodResolver(AddContractSchema),
        defaultValues,
    });

    const onSubmit = async (data: AddContractFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors
        try {
            const fd = new FormData();
            fd.append('employee_id', String(data.employee_id));
            fd.append('contract_end_date_type', String(data.contract_end_date_type));

            fd.append('start_date', format(data.start_date, 'yyyy-MM-dd'));
            fd.append('sign_date', format(data.sign_date, 'yyyy-MM-dd'));
            fd.append('join_date', format(data.join_date, 'yyyy-MM-dd'));
            if (data.test_end_date) fd.append('test_end_date', format(data.test_end_date, 'yyyy-MM-dd'));

            if (data.contract_end_date_type === 'end_date' && data.end_date) {
                fd.append('end_date', format(data.end_date, 'yyyy-MM-dd'));
            } else {
                if (data.end_month) fd.append('end_month', data.end_month);
                if (data.end_year) fd.append('end_year', data.end_year);
            }

            fd.append('currency', String(data.currency));
            fd.append('salary_cycle', String(data.salary_cycle));
            fd.append('salary', String(data.salary));

            if (data.overtime_rate !== undefined) fd.append('overtime_rate', String(data.overtime_rate));
            if (data.housing_allowance !== undefined) fd.append('housing_allowance', String(data.housing_allowance));
            if (data.transportation_allowance !== undefined)
                fd.append('transportation_allowance', String(data.transportation_allowance));

            if (data.contract_type) fd.append('contract_type', data.contract_type);
            if (data.main_contract) fd.append('main_contract', data.main_contract);
         
            if (data.position) fd.append('position', data.position);
            if (data.employee_degree) fd.append('employee_degree', data.employee_degree);
            // if (data.description) fd.append('description', data.description);

            if (!data.skip_allowance && data.allowance_type) fd.append('allowance_type', data.allowance_type);
            if (!data.skip_deduction && data.deduction_type) fd.append('deduction_type', data.deduction_type);

            if (data.file) fd.append('file', data.file);

            await apiPost({
                endpoint: employee ? endpoints.hrContract.update + employee.id : endpoints.hrContract.create,
                body: fd as any,
            });
            setShowSuccessPopup(true);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mb-8">
                    {/* {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )} */}
                    <div>
                        <MainHeading text="معلومات العقد" />
                        <ContractInfo />
                        <MainHeading text="تفاصيل المدة" />
                        <PeriodDetails />
                        <MainHeading text="تفاصيل المرتب" />
                        <SalaryDetails />
                        <MainHeading text="تفاصيل البدلات" />
                        <AllowanceDetails />
                        <MainHeading text="تفاصيل التأمينات" />
                        <InsuranceDetails />

                    </div>
                    <div className="mt-6">
                        <FileInput name="file" label="رفع ملف" multiple={false} maxSize={10 * 1024 * 1024} />
                    </div>
                    <Submission
                        employee={employee}
                        loading={loading}
                        setShowCancelPopup={setShowCancelPopup}
                        setShowSuccessPopup={setShowSuccessPopup}
                        showCancelPopup={showCancelPopup}
                        showSuccessPopup={showSuccessPopup}
                    />
                </form>
            </Form>
        </>
    );
}
