import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { useNavigate } from 'react-router-dom';
import { Employee } from '@/types/employee.types';

interface Props {
    employee?: Employee | null;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
}
export default function Submission({
    employee,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
}: Props) {
    const navigate = useNavigate();

    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row justify-end items-center mt-8">
                {employee ? (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        إلغاء الشكوى
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] bg-red-error-50 text-[#A21515] hover:bg-red-error-600 hover:text-white-blue-50 xl:py-3 border bordr-[#E8EFF6] xl:font-semibold"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {employee ? (
                        <PrimaryButton
                            type="submit"
                            className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6"
                            disabled={loading}
                        >
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton type="submit" className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'حفظ'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    navigate('/human-resources');
                    setShowCancelPopup(false);
                }}
                text1={employee ? 'إلغاء تعديل بيانات الموظف' : 'إلغاء إضافة عقد'}
                text2={
                    employee
                        ? 'أنت على وشك إلغاء عملية تعديل بيانات العقد دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة عقد جديد دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1={employee ? 'إكمال التعديل' : 'إكمال الإضافة'}
                textButton2={employee ? 'إلغاء التعديل' : 'إلغاء الإضافة'}
            />
            <SuccessPopup
                text1={employee ? 'تم تعديل بيانات العقد بنحاح' : 'تم إضافة عقد جديد بنحاح'}
                text2={employee ? 'تم تعديل بيانات العقد بنحاح' : 'تم تسجيل بيانات العقد الجديد بنجاح.'}
                textButton1="العودة لقائمة العقود"
                textButton2={employee ? 'تعديل بيانات اخرى' : 'إضافة عقد أخر'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    navigate('/human-resources/contract-management');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
