import { z } from 'zod';

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
const ALLOWED_FILE_TYPES = [
    'application/pdf',
    'image/jpeg',
    'image/png',
    'image/jpg',
    'image/gif',
    'image/svg+xml',
];

export const AddContractSchema = z
    .object({
        employee_id: z.string().min(1, 'الموظف مطلوب'),
      
        position: z.string().optional(),
        employee_degree: z.string().optional(),
        main_contract: z.string().optional(),
        contract_type: z.string().min(1, 'نوع العمل مطلوب').optional(),
        // description: z.string().optional(),
        //--------------------------------------------------------------------------------------------
        start_date: z.date({ required_error: 'تاريخ البدء مطلوب' }),
        sign_date: z.date({ required_error: 'تاريخ التوقيع مطلوب' }),
        test_end_date: z.date({ required_error: 'تاريخ نهاية الاختبار مطلوب' }).optional(),
        contract_end_date_type: z.enum(['annual', 'end_date'], {
            required_error: 'نوع صلاحية العقد مطلوب',
        }),
        join_date: z.date({ required_error: 'تاريخ الالتحاق مطلوب' }),
        end_date: z.date().optional(),
        end_month: z.string().optional(),
        end_year: z.string().optional(),
        //--------------------------------------------------------------------------------------------
        currency: z.string().default('SAR'),
        salary_cycle: z.string().min(1, 'دورة القبض مطلوبة'),
        salary: z.coerce.number().min(0, 'الراتب غير صحيح'),
        overtime_rate: z.coerce.number().min(0).optional(),
        housing_allowance: z.coerce.number().min(0).optional(),
        transportation_allowance: z.coerce.number().min(0).optional(),
        skip_allowance: z.boolean().default(false),
        skip_deduction: z.boolean().default(false),
        allowance_type: z.string().optional(),
        deduction_type: z.string().optional(),
        file: z
            .instanceof(File)
            .refine((file) => file.size <= MAX_FILE_SIZE, `File must be less than ${MAX_FILE_SIZE}MB`)
            .refine((file) => ALLOWED_FILE_TYPES.includes(file.type), 'Unsupported file type')
            .optional(),
    })
    .superRefine((data, ctx) => {
        if (data.contract_end_date_type === 'annual') {
            if (!data.end_month || data.end_month.trim() === '') {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: 'شهر الانتهاء مطلوب',
                    path: ['end_month'],
                });
            }
            if (!data.end_year || data.end_year.trim() === '') {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: 'سنة الانتهاء مطلوبة',
                    path: ['end_year'],
                });
            }
        }

        if (data.contract_end_date_type === 'end_date' && !data.end_date) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: 'تاريخ الانتهاء مطلوب',
                path: ['end_date'],
            });
        }

        if (!data.skip_allowance && (!data.allowance_type || data.allowance_type.trim() === '')) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: 'نوع البدل مطلوب',
                path: ['allowance_type'],
            });
        }
        if (!data.skip_deduction && (!data.deduction_type || data.deduction_type.trim() === '')) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: 'نوع الخصم مطلوب',
                path: ['deduction_type'],
            });
        }
    });

export type AddContractFormValues = z.infer<typeof AddContractSchema>;
