import SelectInputForm from '@/components/forms/SelectInputForm';
import { FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Checkbox } from '@/components/ui/checkbox';
import { useFormContext, useWatch } from 'react-hook-form';

const allowanceTypeOptions = [
    { value: 'housing', name: 'بدل السكن' },
    { value: 'transportation', name: 'بدل المواصلات' },
];

export default function AllowanceDetails() {
    const { control, setValue } = useFormContext();
    const skipAllowance = useWatch({ control, name: 'skip_allowance' });
    const skipDeduction = useWatch({ control, name: 'skip_deduction' });

    return (
        <div className="mb-6 grid grid-cols-1 gap-6 md:grid-cols-2">
            <div className="space-y-4">
                <SelectInputForm
                    key={`allowance_type-${String(skipAllowance)}`}
                    name="allowance_type"
                    label="نوع البدل "
                    options={allowanceTypeOptions}
                    placeholder="اختر نوع البدل"
                    disabled={skipAllowance}
                />
                <FormField
                    control={control}
                    name="skip_allowance"
                    render={({ field }) => (
                        <FormItem className="flex flex-row items-start gap-3 space-y-0 rounded-md border border-neutral-200 bg-neutral-50/80 p-3">
                            <FormControl>
                                <Checkbox
                                    checked={field.value}
                                    onCheckedChange={(checked) => {
                                        const next = checked === true;
                                        field.onChange(next);
                                        if (next) setValue('allowance_type', '');
                                    }}
                                    className="mt-0.5"
                                />
                            </FormControl>
                            <div className="space-y-1 leading-none">
                                <FormLabel className="text-primery-blue-900 cursor-pointer font-medium text-[15px] leading-snug">
                                    بدون بدل
                                </FormLabel>

                                <FormMessage />
                            </div>
                        </FormItem>
                    )}
                />
            </div>
            {/* <div className="space-y-4">
                <SelectInputForm
                    key={`deduction_type-${String(skipDeduction)}`}
                    name="deduction_type"
                    label="نوع الخصم "
                    options={deductionTypeOptions}
                    placeholder="اختر نوع الخصم"
                    disabled={skipDeduction}
                />
                <FormField
                    control={control}
                    name="skip_deduction"
                    render={({ field }) => (
                        <FormItem className="flex flex-row items-start gap-3 space-y-0 rounded-md border border-neutral-200 bg-neutral-50/80 p-3">
                            <FormControl>
                                <Checkbox
                                    checked={field.value}
                                    onCheckedChange={(checked) => {
                                        const next = checked === true;
                                        field.onChange(next);
                                        if (next) setValue('deduction_type', '');
                                    }}
                                    className="mt-0.5"
                                />
                            </FormControl>
                            <div className="space-y-1 leading-none">
                                <FormLabel className="text-primery-blue-900 cursor-pointer font-medium text-[15px] leading-snug">
                                    بدون خصم
                                </FormLabel>
                            
                                <FormMessage />
                            </div>
                        </FormItem>
                    )}
                />
            </div> */}
        </div>
    );
}
