import TextInputForm from '@/components/forms/TextInputForm';
import { DateInputForm } from '@/components/forms/DateInputForm';

export default function InsuranceDetails() {

    return (
        <div className="mb-6 grid grid-cols-1 gap-6 md:grid-cols-2">
            <TextInputForm name="insurance_type" label="نوع التأمين" placeholder="اختر نوع التأمين" />
            <TextInputForm name="insurance_price" label="قيمة التأمين" placeholder="ادخل قيمة التأمين" />
            <TextInputForm type="number" name="number_of_beneficiaries" label="عدد المستفيدين" placeholder="ادخل عدد المستفيدين" />
           
            <DateInputForm name="insurance_expiry_date" label="تاريخ انتهاء التأمين" placeholder="ادخل تاريخ انتهاء التأمين" />
            <TextInputForm name="insurance_note" label="ملاحظات" placeholder="ادخل ملاحظات التأمين" />
        </div>
    );
}