import SelectInputForm from '@/components/forms/SelectInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import { useMemo } from 'react';

export default function SalaryDetails() {
    const cycleOptions = useMemo(
        () => [
            { value: 'monthly', name: 'شهري' },
            { value: 'weekly', name: 'أسبوعي' },
            { value: 'yearly', name: 'سنوي' },
            { value: 'half_yearly', name: 'نصف سنوي' },
            { value: 'quarterly', name: 'ربع سنوي' },
            { value: 'daily', name: 'يومي' },
        ],
        [],
    );

    return (
        <div className="mb-6 grid grid-cols-1 md:grid-cols-2 gap-6">
            <SelectInputForm
                name="salary_cycle"
                label="دورة القبض "
                options={cycleOptions}
                placeholder="اختر دورة القبض"
            />
            <TextInputForm name="salary" label="الراتب" placeholder="4000" />
            <TextInputForm name="overtime_rate" label="الساعه الاضافية" placeholder="80" />
        </div>
    );
}
