import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import TextAreaInputForm from '@/components/forms/TextAreaInputForm';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Employee } from '@/types/employee.types';
import { useFormContext } from 'react-hook-form';
import { useEffect, useMemo, useState } from 'react';
import TextInputForm from '@/components/forms/TextInputForm';

export default function ContractInfo() {
    const { watch } = useFormContext();
    const [employees, setEmployees] = useState<{ name: string; value: string }[]>([]);
    const [employeesError, setEmployeesError] = useState<string | null>(null);

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.simpleList });
                const options = (response.data.data as Employee[]).map((employee: Employee) => {
                    return { name: employee.name, value: String(employee.id) };
                });
                setEmployees(options);
                setEmployeesError(null);
            } catch (error) {
                setEmployeesError('Error fetching employees. Please try again later.');
            }
        };

        fetchEmployees();
    }, []);

    const contractTypeOptions = useMemo(
        () => [
            { value: 'full_time', name: 'دوام كامل' },
            { value: 'part_time', name: 'دوام جزئي' },
        ],
        [],
    );

    return (
        <div className="mb-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <SearchableSelectInputForm
                    name="employee_id"
                    placeholder="ادخل اسم الموظف"
                    label="اسم الموظف"
                    options={employees}
                    error={employeesError}
                    data={true}
                />
                {/* <TextInputForm name="employee_number" label="الكود" placeholder="#899657" /> */}

                <TextInputForm name="position" label="المسمى الوظيفي" placeholder="ادخل المسمى الوظيفي" />
                <TextInputForm name="job_level" label="المستوى الوظيفي" placeholder="ادخل المستوى الوظيفي" />
                <TextInputForm name="main_contract" label="العقد الاساسي" placeholder="ادخل العقد الاساسي" />
                <SelectInputForm
                    name="contract_type"
                    label="نوع العمل "
                    options={contractTypeOptions}
                    placeholder="اختر نوع العمل"
                />

            </div>
            {/* <div className="w-full mt-6">
                <TextAreaInputForm
                    className="flex flex-col min-h-[157px]"
                    name="description"
                    label="الوصف"
                    placeholder="اكتب وصفًا مختصرًا (اختياري)"
                />
            </div> */}
        </div>
    );
}
