import { DateInputForm } from '@/components/forms/DateInputForm';
import { RadioDatePickerGroup } from './RadioDatePickerGroup';

export default function PeriodDetails() {
    return (
        <div className="mb-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <DateInputForm name="join_date" label="تاريخ الالتحاق" placeholder="2025/05/20" />
                <DateInputForm name="test_end_date" label="تاريخ نهاية الاختبار" placeholder="2025/05/20" />
                <DateInputForm name="start_date" label="تاريخ البدء الفعلي" placeholder="2025/05/20" />
                <DateInputForm name="sign_date" label="تاريخ التوقيع" placeholder="2025/05/20" />
            </div>

            <div className="my-4">
                <p className="text-primery-blue-900 mb-2 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                    نوع صلاحية العقد
                </p>
                <RadioDatePickerGroup
                    name="contract_end_date_type"
                    date1Name="date1"
                    date2Name="date2"
                    label1="مدة سنوية"
                    label2="تاريخ الانتهاء"
                />
            </div>
        </div>
    );
}
